    trigFinished : R_TRIG;

    tmp_bottle_edge : BOOL;
    tmp_clean_edge : BOOL;
    tmp_fill_edge : BOOL;
    tmp_cap_edge : BOOL;
    tmp_pack_edge : BOOL;
    tmp_finished_edge : BOOL;
END_VAR

trigBottle(CLK := bottleSensor);
